package de.corporate.lc.imports.service;
import de.corporate.lc.imports.domain.SwiftImportRecord; import de.corporate.lc.imports.repository.SwiftImportRecordRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import java.util.List;
@Service public class SwiftImportHistoryService {private final SwiftImportRecordRepository repo;public SwiftImportHistoryService(SwiftImportRecordRepository r){repo=r;}@Transactional(propagation=Propagation.REQUIRES_NEW) public void record(String filename,String type,String reference,String status,String message){SwiftImportRecord x=new SwiftImportRecord();x.setFilename(filename==null||filename.isBlank()?"Manuelle Eingabe":filename.trim());x.setMessageType(type);x.setReference(reference);x.setStatus(status);x.setMessage(message);repo.save(x);}public List<SwiftImportRecord> recent(){return repo.findTop20ByOrderByImportedAtDesc();}}
